17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Objects;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
108	        if (hasReachedDailyRegistrationLimit()) {
109	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
110	        }
111	        if (hasReachedCityOwnerLimit(owner.getCity())) {
112	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
113	        }
114	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
115	            return new ResponseEntity<>(HttpStatus.CONFLICT);
116	        }
117	        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
118	        owner.setSharesHousehold(sharesHousehold(owner.getAddress(), owner.getCity()));
119	        owner.setCity(resolveCity(owner.getCity()));
120	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
121	        owner.setMembershipNumber(membershipNumber);
122	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
123	        owner.setMembershipTier(membershipNumber <= MAX_FOUNDING_OWNERS ? "FOUNDING" : "STANDARD");
124	        this.clinicService.saveOwner(owner);
125	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
126	        headers.setLocation(UriComponentsBuilder.newInstance()
127	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
128	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
134	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
135	        if (currentOwner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        currentOwner.setAddress(ownerFieldsDto.getAddress());
139	        currentOwner.setCity(ownerFieldsDto.getCity());
140	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
141	        currentOwner.setLastName(ownerFieldsDto.getLastName());
142	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
143	        this.clinicService.saveOwner(currentOwner);
144	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Transactional
149	    @Override
150	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        this.clinicService.deleteOwner(owner);
156	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
162	        Owner owner = this.clinicService.findOwnerById(ownerId);
163	        if (owner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        HttpHeaders headers = new HttpHeaders();
167	        Pet pet = petMapper.toPet(petFieldsDto);
168	        owner.setId(ownerId);
169	        pet.setOwner(owner);
170	        pet.getType().setName(null);
171	        this.clinicService.savePet(pet);
172	        PetDto petDto = petMapper.toPetDto(pet);
173	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
174	            .buildAndExpand(pet.getId()).toUri());
175	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
181	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
182	        if (currentOwner != null) {
183	            Pet currentPet = this.clinicService.findPetById(petId);
184	            if (currentPet != null) {
185	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
186	                currentPet.setName(petFieldsDto.getName());
187	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
188	                this.clinicService.savePet(currentPet);
189	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
190	            }
191	        }
192	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
198	        HttpHeaders headers = new HttpHeaders();
199	        Visit visit = visitMapper.toVisit(visitFieldsDto);
200	        Pet pet = new Pet();
201	        pet.setId(petId);
202	        visit.setPet(pet);
203	        this.clinicService.saveVisit(visit);
204	        VisitDto visitDto = visitMapper.toVisitDto(visit);
205	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
206	            .buildAndExpand(visit.getId()).toUri());
207	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
208	    }
209	
210	
211	    /**
212	     * The number of owners at the head of the registration sequence that receive the
213	     * {@code 'FOUNDING'} membership tier. The first {@value #MAX_FOUNDING_OWNERS} owners ever
214	     * created are {@code 'FOUNDING'}; all later owners are {@code 'STANDARD'}.
215	     */
216	    private static final int MAX_FOUNDING_OWNERS = 100;
217	
218	    /**
219	     * The maximum number of owners that may be registered on any single calendar day.
220	     */
221	    private static final long MAX_DAILY_REGISTRATIONS = 20;
222	
223	    /**
224	     * Determines whether the daily owner-registration limit has already been reached. Owners are
225	     * counted by their {@link Owner#getRegistrationDate() registration date}, so once
226	     * {@value #MAX_DAILY_REGISTRATIONS} owners have been registered with today's date, no further
227	     * owners may be created today.
228	     *
229	     * @return {@code true} if today's registration limit has been reached
230	     */
231	    private boolean hasReachedDailyRegistrationLimit() {
232	        LocalDate today = LocalDate.now();
233	        long registeredToday = this.clinicService.findAllOwners().stream()
234	            .filter(existing -> today.equals(existing.getRegistrationDate()))
235	            .count();
236	        return registeredToday >= MAX_DAILY_REGISTRATIONS;
237	    }
238	
239	    /**
240	     * The maximum number of owners that may be registered in any single city.
241	     */
242	    private static final long MAX_OWNERS_PER_CITY = 8;
243	
244	    /**
245	     * Determines whether the given city has already reached its owner limit. Owners are matched to
246	     * the city using {@link #normalize(String)}, so the count ignores letter case and any
247	     * surrounding or repeated whitespace. Once {@value #MAX_OWNERS_PER_CITY} owners live in a city,
248	     * no further owners may be created there.
249	     *
250	     * @param city the city of the new owner, may be {@code null}
251	     * @return {@code true} if the city already contains {@value #MAX_OWNERS_PER_CITY} owners
252	     */
253	    private boolean hasReachedCityOwnerLimit(String city) {
254	        String normalized = normalize(city);
255	        long ownersInCity = this.clinicService.findAllOwners().stream()
256	            .filter(existing -> Objects.equals(normalize(existing.getCity()), normalized))
257	            .count();
258	        return ownersInCity >= MAX_OWNERS_PER_CITY;
259	    }
260	
261	    /**
262	     * Builds the customer code for a newly created owner, formatted as
263	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
264	     * already registered in that city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
265	     *
266	     * @param city the city of the new owner
267	     * @return the assigned customer code
268	     */
269	    private String nextCustomerCode(String city) {
270	        long ownersInCity = this.clinicService.findAllOwners().stream()
271	            .filter(existing -> Objects.equals(
272	                normalize(existing.getCity()), normalize(city)))
273	            .count();
274	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
275	    }
276	
277	    /**
278	     * Resolves the city to store for a newly created owner. The city is title-cased (so
279	     * {@code "new york"} becomes {@code "New York"}), unless an owner already lives in that
280	     * city, in which case the existing owner's exact spelling of the city name is reused. Cities
281	     * are matched using {@link #normalize(String)}, so the match ignores letter case and any
282	     * surrounding or repeated whitespace.
283	     *
284	     * @param city the city supplied for the new owner, may be {@code null}
285	     * @return the city to store, or {@code null} if the input was {@code null}
286	     */
287	    private String resolveCity(String city) {
288	        if (city == null) {
289	            return null;
290	        }
291	        String normalized = normalize(city);
292	        if (!normalized.isEmpty()) {
293	            for (Owner existing : this.clinicService.findAllOwners()) {
294	                if (normalized.equals(normalize(existing.getCity()))) {
295	                    return existing.getCity();
296	                }
297	            }
298	        }
299	        return toTitleCase(city);
300	    }
301	
302	    /**
303	     * Title-cases free-form text by upper-casing the first letter of each whitespace-separated word
304	     * and lower-casing the remaining letters, preserving the original whitespace. For example
305	     * {@code "new  YORK"} becomes {@code "New  York"}.
306	     *
307	     * @param value the raw value, never {@code null}
308	     * @return the title-cased value
309	     */
310	    private static String toTitleCase(String value) {
311	        StringBuilder result = new StringBuilder(value.length());
312	        boolean startOfWord = true;
313	        for (int i = 0; i < value.length(); i++) {
314	            char c = value.charAt(i);
315	            if (Character.isWhitespace(c)) {
316	                startOfWord = true;
317	                result.append(c);
318	            } else if (startOfWord) {
319	                result.append(Character.toTitleCase(c));
320	                startOfWord = false;
321	            } else {
322	                result.append(Character.toLowerCase(c));
323	            }
324	        }
325	        return result.toString();
326	    }
327	
328	    /**
329	     * Counts how many existing owners share the given last name. Last names are matched using
330	     * {@link #normalize(String)}, so the count ignores letter case and any surrounding or repeated
331	     * whitespace. This is evaluated against the owners present at the moment the new owner is
332	     * created, before the new owner is persisted, so the new owner does not count itself.
333	     *
334	     * @param lastName the last name of the new owner, may be {@code null}
335	     * @return the number of existing owners sharing the same last name
336	     */
337	    private int countNamesakes(String lastName) {
338	        String normalized = normalize(lastName);
339	        return (int) this.clinicService.findAllOwners().stream()
340	            .filter(existing -> normalized.equals(normalize(existing.getLastName())))
341	            .count();
342	    }
343	
344	    /**
345	     * Determines whether the new owner shares a household with an existing owner, meaning another
346	     * owner already has the same address and city. Both the address and the city are matched using
347	     * {@link #normalize(String)}, so the comparison ignores letter case and any surrounding or
348	     * repeated whitespace. This is evaluated against the owners present at the moment the new owner
349	     * is created, before the new owner is persisted, so the new owner does not count itself.
350	     *
351	     * @param address the address of the new owner, may be {@code null}
352	     * @param city    the city of the new owner, may be {@code null}
353	     * @return {@code true} if an existing owner already has the same address and city
354	     */
355	    private boolean sharesHousehold(String address, String city) {
356	        String normalizedAddress = normalize(address);
357	        String normalizedCity = normalize(city);
358	        return this.clinicService.findAllOwners().stream()
359	            .anyMatch(existing -> normalizedAddress.equals(normalize(existing.getAddress()))
360	                && normalizedCity.equals(normalize(existing.getCity())));
361	    }
362	
363	    /**
364	     * Determines whether the given telephone number is already used by any other owner.
365	     *
366	     * @param owner the candidate owner
367	     * @return {@code true} if an owner with the same telephone number already exists in the data store
368	     */
369	    private boolean isDuplicateOwner(Owner owner) {
370	        return this.clinicService.findAllOwners().stream()
371	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
372	    }
373	
374	    /**
375	     * Determines whether the given email address is already used by any other owner. An owner
376	     * without an email address is never considered a duplicate on this criterion. Email addresses
377	     * are compared using {@link #normalize(String)} so the check ignores letter case and any
378	     * surrounding or repeated whitespace.
379	     *
380	     * @param owner the candidate owner
381	     * @return {@code true} if the owner provides an email already used by an existing owner
382	     */
383	    private boolean isDuplicateEmail(Owner owner) {
384	        String email = normalize(owner.getEmail());
385	        if (email.isEmpty()) {
386	            return false;
387	        }
388	        return this.clinicService.findAllOwners().stream()
389	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
390	    }
391	
392	    /**
393	     * Normalizes a telephone number to digits only by stripping spaces, dashes and parentheses, so
394	     * that a value such as {@code "(613) 555-0100"} is stored and compared as {@code "6135550100"}.
395	     * This is applied before an owner is stored and before the telephone-uniqueness check, so two
396	     * differently formatted representations of the same number are treated as duplicates. A
397	     * {@code null} value is returned unchanged.
398	     *
399	     * @param telephone the raw telephone number, may be {@code null}
400	     * @return the digits-only telephone number, or {@code null} if the input was {@code null}
401	     */
402	    private static String normalizeTelephone(String telephone) {
403	        if (telephone == null) {
404	            return null;
405	        }
406	        return telephone.replaceAll("[\\s()-]", "");
407	    }
408	
409	    /**
410	     * Normalizes free-form text for duplicate detection so that comparisons ignore letter case and
411	     * surrounding or repeated whitespace: the value is trimmed, runs of internal whitespace are
412	     * collapsed to a single space and the result is lower-cased. This is what makes
413	     * {@code "  john   smith "} and {@code "John Smith"} count as the same value when detecting
414	     * duplicates. A {@code null} value normalizes to the empty string.
415	     *
416	     * @param value the raw value, may be {@code null}
417	     * @return the normalized value, never {@code null}
418	     */
419	    private static String normalize(String value) {
420	        if (value == null) {
421	            return "";
422	        }
423	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
424	    }
425	
426	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
427	    @Override
428	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
429	        Owner owner = this.clinicService.findOwnerById(ownerId);
430	        if (owner != null) {
431	            Pet pet = owner.getPet(petId);
432	            if (pet != null) {
433	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
434	            }
435	        }
436	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
437	    }
438	}
